for id in kcqql3xqbrmzsmeoon57ncbnie v42vz4ycbzr3vdao4won3j5c24; do
  echo "===== ITEM $id =====";
  op item get "$id" --format json 2>&1 | jq -r '
    "title: \(.title)",
    (.urls // [] | .[] | "url: \(.href)"),
    (.fields[] | select(.value != null) | "field[\(.id)] label=\(.label) type=\(.type) value=\(if .type=="CONCEALED" then "***HIDDEN***" else .value end)")
  ';
  echo;
done

cd /Users/myankelev/Code/random/cipher-box
PR=515; OWNER=FSM1; NAME=cipher-box
echo "=== unresolved review threads ==="
env -u GITHUB_TOKEN gh api graphql -f query="
{
  repository(owner: \"$OWNER\", name: \"$NAME\") {
    pullRequest(number: $PR) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          isOutdated
          comments(first: 10) {
            nodes { author { login } body path line createdAt }
          }
        }
      }
    }
  }
}" 2>&1 | jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false)] | {unresolved_count: length, threads: .}'
echo
echo "=== review summaries (author + state + body length) ==="
env -u GITHUB_TOKEN gh api repos/$OWNER/$NAME/pulls/$PR/reviews --jq '.[] | {author: .user.login, state: .state, submitted: .submittedAt, body_len: (.body|length)}' 2>&1

